#include <zephyr/kernel.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/rtio_work.h>

/**
 * @brief Callback for handling the submission result
 *
 * @param cqe The completion queue entry for this submission
 */
static void rtio_work_req_handler(struct rtio_cqe *cqe)
{
	struct k_work *work = cqe->userdata;

	k_work_submit(work);
}

int rtio_work_req_submit(struct rtio *r, struct rtio_sqe *req, struct k_work *work)
{
	if (r == NULL || req == NULL || work == NULL) {
		return -EINVAL;
	}

	req->userdata = work;
	req->notify_cb = rtio_work_req_handler;

	return rtio_submit(r, req);
}
